async function seed() {
  console.log(`Seeding ${DATA.length} curriculum rows (Nivel Secundario)...\n`)
  let inserted = 0
  let skipped = 0
  let errors = 0

  for (const entry of DATA) {
    try {
      await sql`
        INSERT INTO curriculum (jurisdiccion, nivel, materia, grado, eje, temas)
        VALUES (
          ${entry.jurisdiccion ?? DEFAULT_JURISDICTION},
          ${entry.nivel},
          ${entry.materia},
          ${entry.grado},
          ${entry.eje},
          ${JSON.stringify(entry.temas)}::jsonb
        )
      `
      inserted++
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err)
      if (msg.includes('duplicate') || msg.includes('unique')) {
        skipped++
      } else {
        errors++
        console.error(`  ✗ [${entry.materia} / ${entry.grado} / ${entry.eje.slice(0, 40)}]: ${msg}`)
      }
    }
  }

  console.log(`\n✅ Done.`)
  console.log(`   Inserted : ${inserted}`)
  console.log(`   Skipped  : ${skipped}  (duplicate rows)`)
  console.log(`   Errors   : ${errors}`)
  process.exit(0)
}

seed().catch((err) => {
  console.error('Seeder failed:', err)
  process.exit(1)
})
